import groovy.json.JsonSlurper
import groovy.json.JsonOutput
import java.nio.charset.StandardCharsets
import org.apache.nifi.processor.io.StreamCallback
import org.apache.nifi.processor.io.InputStreamCallback
import java.security.MessageDigest

flowFile = session.get()
if (!flowFile) {
    return
}


def rawId = null

def getID(String url) {
    if (!url) return null
    // Hash the full URL string (avoid creating a URI to prevent URISyntaxException)
    def md5 = MessageDigest.getInstance("MD5")
    def hashBytes = md5.digest(url.getBytes(StandardCharsets.UTF_8))
    return hashBytes.collect { String.format('%02x', it) }.join('')
}

flowFile = session.write(flowFile, { inputStream, outputStream ->
    def content = new String(inputStream.bytes, StandardCharsets.UTF_8)
        // strip UTF-8 BOM (U+FEFF) if present at the start of the stream
        if (content.length() > 0 && content.charAt(0) == '\uFEFF') {
            content = content.substring(1)
        }
        def jsonContent = new JsonSlurper().parseText(content)

    def firstItem = null
    if (jsonContent instanceof List) {
        if (jsonContent.size() > 0) {
            firstItem = jsonContent[0]
        } else {
            firstItem = null
        }
    } else {
        firstItem = jsonContent
    }

    def id = getID(firstItem.url)
    firstItem.id = id
    rawId = id
    outputStream.write(JsonOutput.toJson(firstItem).getBytes(StandardCharsets.UTF_8))

} as StreamCallback)


if (rawId) {
    flowFile = session.putAttribute(flowFile, 'id', rawId)
}

session.transfer(flowFile, REL_SUCCESS)

@GrabConfig(systemClassLoader=true)
import groovy.json.JsonSlurper
import groovy.json.JsonOutput
import groovy.transform.CompileStatic
import java.nio.charset.StandardCharsets
import org.apache.nifi.processor.io.InputStreamCallback
import org.apache.nifi.processor.io.OutputStreamCallback

@CompileStatic
class Utils {
    static String readUtf8NoBom(InputStream in) {
        byte[] bytes = in.bytes
        if (bytes.length >= 3 &&
            (bytes[0] & 0xFF) == 0xEF &&
            (bytes[1] & 0xFF) == 0xBB &&
            (bytes[2] & 0xFF) == 0xBF) {
            return new String(bytes, 3, bytes.length - 3, StandardCharsets.UTF_8)
        }
        String s = new String(bytes, StandardCharsets.UTF_8)
        return (s.length() > 0 && s.charAt(0) == '\uFEFF' as char) ? s.substring(1) : s
    }

    static byte[] toJsonBytes(Object o) {
        return JsonOutput.toJson(o).getBytes(StandardCharsets.UTF_8)
    }
}

def parent = session.get()
if (!parent) return

final JsonSlurper slurper = new JsonSlurper()

// ======================================================
//  LOAD PARAMETER: excludedModels  (robust handling)
// ======================================================
def excludedModels = []
try {
    def raw = context.getProperty("excludedModels")
                     .evaluateAttributeExpressions(parent)
                     .getValue()

    log.info("excludedModels raw = " + raw)

    if (raw) {
        raw = raw.trim()

        if (raw.startsWith("[") && raw.endsWith("]")) {
            // JSON array
            excludedModels = slurper.parseText(raw) as List
        } else if (raw.contains(",")) {
            // "a,b,c"
            excludedModels = raw.split(",")*.trim()
        } else {
            // Single string
            excludedModels = [raw]
        }
    }
} catch (Exception ex) {
    log.error("Failed to parse excludedModels: " + ex.message)
    excludedModels = []
}

log.info("excludedModels parsed = " + excludedModels)
// ======================================================


// ======================================================
//  READ PARENT FLOWFILE CONTENT
// ======================================================
String content = ''
session.read(parent, { InputStream in ->
    content = Utils.readUtf8NoBom(in)
} as InputStreamCallback)


// ======================================================
//  PARSE JSON ROOT (array or object)
// ======================================================
def root
try {
    root = slurper.parseText(content)
} catch (Exception e) {
    log.error("Invalid JSON input: " + e.message)
    session.transfer(parent, REL_FAILURE)
    return
}

List items = (root instanceof List) ? (List) root : [root]


// ======================================================
//  PROCESS ITEMS
// ======================================================
for (def itemObj : items) {

    // Nếu item không phải object → vẫn xuất ra
    if (!(itemObj instanceof Map)) {
        def ff = session.create(parent)
        ff = session.write(ff, { out ->
            out.write(Utils.toJsonBytes([itemObj]))
        } as OutputStreamCallback)
        session.transfer(ff, REL_SUCCESS)
        continue
    }

    Map item = (Map) itemObj

    // --------------------------------------------------
    // CHECK EXCLUDED MODELS
    // --------------------------------------------------
    def modelName = item.get("modelName")?.toString()
    if (modelName && excludedModels.any { it.equalsIgnoreCase(modelName) }) {
        log.info(">>> SKIP ITEM vì modelName '${modelName}' nằm trong excludedModels")
        continue
    }
    // --------------------------------------------------


    // --------------------------------------------------
    // HANDLE actualResult (string JSON or object)
    // --------------------------------------------------
    def ar = item.get("actualResult")
    if (ar instanceof CharSequence) {
        try {
            ar = slurper.parseText(ar.toString())
        } catch (Exception ignored) {}
    }

    Object outPayload
    if (ar instanceof Map) {
        outPayload = ((Map) ar).values().toList()
    } else if (ar instanceof List) {
        outPayload = ar
    } else {
        outPayload = [ar]
    }


    // --------------------------------------------------
    // CREATE CHILD FLOWFILE
    // --------------------------------------------------
    def child = session.create(parent)
    child = session.write(child, { OutputStream os ->
        os.write(Utils.toJsonBytes(outPayload))
    } as OutputStreamCallback)

    if (modelName) {
        child = session.putAttribute(child, "modelName", modelName)
    }

    if (item.containsKey("platform") && item.get("platform") != null) {
        child = session.putAttribute(child, "platform", String.valueOf(item.get("platform")))
    }

    session.transfer(child, REL_SUCCESS)
}


// ======================================================
// REMOVE ORIGINAL FLOWFILE
// ======================================================
session.remove(parent)

import groovy.json.JsonSlurper
import groovy.json.JsonOutput
import java.nio.charset.StandardCharsets
import org.apache.nifi.processor.io.StreamCallback

flowFile = session.get()
if (!flowFile) return

def filterJson(input) {
    if (input instanceof Map) {
        input.findAll { k, v -> v != null && !(v instanceof Collection && v.isEmpty()) }
                .collectEntries { k, v -> [k, filterJson(v)] }
    } else if (input instanceof Collection) {
        input.findAll { it != null && !(it instanceof Collection && it.isEmpty()) }
                .collect { filterJson(it) }
    } else {
        return input
    }
}

def content = ''
session.read(flowFile, { inputStream ->
    content = new String(inputStream.bytes, StandardCharsets.UTF_8)
} as InputStreamCallback)

if (!content || content.trim() == '' || content.trim() == 'null') {
    session.remove(flowFile) 
    return
}

def json = new JsonSlurper().parseText(content)

def filterJson = filterJson(json)

flowFile = session.write(flowFile, { out ->
		out.write(JsonOutput.toJson(filterJson).getBytes(StandardCharsets.UTF_8))
} as OutputStreamCallback)

session.transfer(flowFile, REL_SUCCESS)

@GrabConfig(systemClassLoader=true)
import groovy.json.JsonSlurper
import groovy.json.JsonOutput
import groovy.transform.CompileStatic
import java.nio.charset.StandardCharsets
import org.apache.nifi.processor.io.InputStreamCallback
import org.apache.nifi.processor.io.OutputStreamCallback

@CompileStatic
class Utils {
    static String readUtf8NoBom(InputStream inputStream) {
        byte[] b = inputStream.bytes
        if (b.length >= 3 && (b[0] & 0xFF) == 0xEF && (b[1] & 0xFF) == 0xBB && (b[2] & 0xFF) == 0xBF) {
            return new String(b, 3, b.length - 3, StandardCharsets.UTF_8)
        }
        String s = new String(b, StandardCharsets.UTF_8)
        return (s && s.charAt(0) == '\uFEFF' as char) ? s.substring(1) : s
    }

    static boolean notEmpty(Object v) {
        if (v == null) return false
        if (v instanceof Collection) return !((Collection) v).isEmpty()
        return true
    }

    static Object clean(Object node) {
        if (node instanceof Map) {
            Map m = (Map) node
            Map out = new LinkedHashMap(m.size())
            for (def e : m.entrySet()) {
                Object cv = clean(e.value)
                if (cv != null && notEmpty(cv)) out.put(String.valueOf(e.key), cv)
            }
            return out
        } else if (node instanceof Collection) {
            List lst = new ArrayList(((Collection) node).size())
            for (Object it : (Collection) node) {
                Object cv = clean(it)
                if (cv != null && notEmpty(cv)) lst.add(cv)
            }
            return lst
        } else {
            return node
        }
    }

    /**
     * Chuẩn hóa map đầu vào về bộ key parser (NotificationData):
     * - platform, notification_id, uid, created_time, text, url
     * Chấp nhận thêm schema đã rename: platform_alias, message_id, platform_uid, received_time, raw
     * uid chỉ lấy từ uid/platform_uid đầu vào — không map account_id vào uid (account_id giữ riêng cho id/result).
     */
    static Map toCanonicalNotificationMap(Map m) {
        if (m == null) return null
        Map c = new LinkedHashMap()
        c.put('platform', m.get('platform') ?: m.get('platform_alias'))
        c.put('notification_id', m.get('notification_id') ?: m.get('message_id'))
        c.put('uid', m.get('uid') ?: m.get('platform_uid'))
        c.put('account_id', m.get('account_id'))
        c.put('created_time', m.containsKey('created_time') ? m.get('created_time') : m.get('received_time'))
        c.put('text', m.get('text') ?: m.get('raw'))
        c.put('url', m.get('url'))
        if (m.containsKey('type')) c.put('type', m.get('type'))
        return c
    }

    /**
     * Đủ dữ liệu để xuất bản ghi: (uid hoặc platform_uid) hoặc account_id khi không có uid + message_id.
     */
    static boolean isValidNotificationInput(Map m) {
        if (m == null) return false
        Map c = toCanonicalNotificationMap(m)
        def uid = c.get('uid')?.toString()?.trim()
        def accountId = c.get('account_id')?.toString()?.trim()
        def notificationId = c.get('notification_id')?.toString()?.trim()
        return ((uid as boolean) || (accountId as boolean)) && (notificationId as boolean)
    }

    static boolean isValidNotificationItem(Object item) {
        if (item instanceof Map) return isValidNotificationInput((Map) item)
        return false
    }

    /** id = platform_alias_<uid hoặc account_id>_message_id — phần giữa: platform_uid nếu có, không thì account_id (không ghi account_id vào platform_uid). */
    static String makeId(Map out) {
        def platformAlias = out.get('platform_alias')?.toString()?.trim() ?: 'facebook.com'
        def platformUid = out.get('platform_uid')?.toString()?.trim()
        def accountId = out.get('account_id')?.toString()?.trim()
        def idMiddle = (platformUid as boolean) ? platformUid : (accountId ?: '')
        def messageId = out.get('message_id')?.toString()?.trim() ?: ''
        return "${platformAlias}_${idMiddle}_${messageId}"
    }

    static Map normalizeToOutput(Map m) {
        Map c = toCanonicalNotificationMap(m)
        Map item = new LinkedHashMap()
        item.put('platform_alias', c.get('platform')?.toString()?.trim() ?: 'facebook.com')
        item.put('message_id', c.get('notification_id'))
        def uid = c.get('uid')?.toString()?.trim()
        if (uid as boolean) {
            item.put('platform_uid', uid)
        }
        def accountId = c.get('account_id')?.toString()?.trim()
        if (accountId as boolean) {
            item.put('account_id', accountId)
        }
        item.put('received_time', c.get('created_time'))
        item.put('raw', c.get('text'))
        item.put('url', c.get('url'))
        if (c.containsKey('type')) item.put('type', c.get('type'))
        item.put('id', makeId(item))
        return item
    }
}

def flowFile = session.get()
if (!flowFile) return

try {
    String content = ''
    session.read(flowFile, { InputStream inputStream ->
        content = Utils.readUtf8NoBom(inputStream)
    } as InputStreamCallback)

    if (content == null || content.trim().isEmpty() || content.trim().equalsIgnoreCase('null')) {
        session.remove(flowFile)
        return
    }

    def json
    try {
        json = new JsonSlurper().parseText(content)
    } catch (Exception e) {
        session.transfer(flowFile, REL_FAILURE)
        return
    }

    json = Utils.clean(json)

    boolean ok = false
    List normalized = new ArrayList()

    if (json instanceof Map) {
        Map m = (Map) json
        if (Utils.isValidNotificationInput(m)) {
            normalized.add(Utils.normalizeToOutput(m))
            ok = true
        }
    } else if (json instanceof List) {
        List lst = (List) json
        List valid = lst.findAll { Utils.isValidNotificationItem(it) }
        valid.each { Map m -> normalized.add(Utils.normalizeToOutput(m)) }
        ok = !normalized.isEmpty()
    }

    if (!ok || normalized.isEmpty()) {
        session.transfer(flowFile, REL_FAILURE)
        return
    }

    def jsonOut = normalized
    byte[] outBytes = JsonOutput.toJson(jsonOut).getBytes(StandardCharsets.UTF_8)
    flowFile = session.write(flowFile, { OutputStream os -> os.write(outBytes) } as OutputStreamCallback)
    flowFile = session.putAttribute(flowFile, 'record.count', String.valueOf(normalized.size()))
    session.transfer(flowFile, REL_SUCCESS)

} catch (Exception e) {
    log.error("ExecuteScript error", e)
    session.transfer(flowFile, REL_FAILURE)
}

import groovy.json.JsonSlurper
import groovy.json.JsonOutput
import java.nio.charset.StandardCharsets
import org.apache.nifi.processor.io.InputStreamCallback
import org.apache.nifi.processor.io.OutputStreamCallback

def flowFile = session.get()
if (!flowFile) return

def asText(value) {
    if (value == null) return null
    def text = value.toString().trim()
    return text ? text : null
}

def asNumber(value) {
    if (value == null || value instanceof Number) {
        return value
    }

    def text = value.toString().trim()
    if (!text) return null

    try {
        return text.contains('.') ?
            new BigDecimal(text) : Long.valueOf(text)
    } catch (Exception ignored) {
        return null
    }
}

def asLong(value) {
    def number = asNumber(value)
    return number instanceof Number ? number.longValue() : null
}

def asInt(value) {
    def number = asNumber(value)
    return number instanceof Number ? number.intValue() : null
}

def asBoolean(value) {
    if (value == null) return null
    if (value instanceof Boolean) return value

    if (value instanceof Number) {
        if (value == 1) return true
        if (value == 0) return false
        return null
    }

    switch (value.toString().trim().toLowerCase()) {
        case 'true':
        case '1':
        case 'yes':
            return true
        case 'false':
        case '0':
        case 'no':
            return false
        default:
            return null
    }
}

def asUrlList(value) {
    if (value == null) return null

    def items = value instanceof Collection ? value : [value]
    def urls = items.collect { asText(it) }
                     .findAll { it }
                     .unique()

    return urls ? urls : null
}

def sanitizeJson(value) {
    if (value == null) return null

    if (value instanceof Map) {
        def result = [:]

        value.each { k, v ->
            def cleaned = sanitizeJson(v)

            if (cleaned != null &&
                !(cleaned instanceof Collection && cleaned.isEmpty()) &&
                !(cleaned instanceof Map && cleaned.isEmpty()) &&
                !(cleaned instanceof String && cleaned.trim().isEmpty())) {
                result[k] = cleaned
            }
        }

        return result
    }

    if (value instanceof Collection) {
        return value.collect { sanitizeJson(it) }
                    .findAll { v ->
                        v != null &&
                        !(v instanceof Collection && v.isEmpty()) &&
                        !(v instanceof Map && v.isEmpty()) &&
                        !(v instanceof String && v.trim().isEmpty())
                    }
    }

    return value
}

def toShopReview(raw) {
    if (!(raw instanceof Map)) return null

    def reviewId = asText(raw.review_id)

    // review_id là khóa nhận diện của model.
    if (!reviewId) return null

    return [
        review_id              : reviewId,
        product_id             : asText(raw.product_id),
        sku_id                 : asText(raw.sku_id),
        reviewer_id            : asText(raw.reviewer_id),
        review_rating          : asInt(raw.review_rating),
        review_time             : asLong(raw.review_time),
        review_time_format      : asText(raw.review_time_format),
        is_verified_purchase    : asBoolean(raw.is_verified_purchase),
        is_incentivized_review  : asBoolean(raw.is_incentivized_review),
        product_name            : asText(raw.product_name),
        reviewer_name           : asText(raw.reviewer_name),
        reviewer_avatar_url     : asText(raw.reviewer_avatar_url),
        review_text             : asText(raw.review_text),
        display_image_url       : asText(raw.display_image_url),
        review_images           : asUrlList(raw.review_images),
        sku_specification       : asText(raw.sku_specification),
        review_country          : asText(raw.review_country),
        domain                  : asText(raw.domain) ?: 'shop.tiktok.com'
    ]
}

def unwrapActualResult(value) {
    if (!(value instanceof String)) return value

    def text = value.trim()

    if (!text || text == 'null') return []

    try {
        return new JsonSlurper().parseText(text)
    } catch (Exception ignored) {
        return []
    }
}

def collectReviews(node, reviews) {
    if (node instanceof Collection) {
        node.each { collectReviews(it, reviews) }
        return
    }

    if (!(node instanceof Map)) return

    // Envelope: { modelName, actualResult }
    if (node.containsKey('modelName')) {
        if (node.modelName?.toString() == 'TikTokShopReview') {
            collectReviews(
                unwrapActualResult(node.actualResult),
                reviews
            )
        }
        return
    }

    // Hỗ trợ review object trực tiếp.
    def review = toShopReview(node)

    if (review != null) {
        reviews << review
    }
}

def content = ''

session.read(flowFile, { inputStream ->
    content = new String(
        inputStream.bytes,
        StandardCharsets.UTF_8
    )
} as InputStreamCallback)

if (!content?.trim() || content.trim() == 'null') {
    session.remove(flowFile)
    return
}

def parsed

try {
    parsed = new JsonSlurper().parseText(content)
} catch (Exception e) {
    log.error('Invalid input JSON: ' + e.message, e)
    session.transfer(flowFile, REL_FAILURE)
    return
}

def reviews = []
collectReviews(parsed, reviews)

def cleaned = sanitizeJson(reviews)

if (!(cleaned instanceof Collection) || cleaned.isEmpty()) {
    session.remove(flowFile)
    return
}

flowFile = session.write(flowFile, { outputStream ->
    outputStream.write(
        JsonOutput.toJson(cleaned).getBytes(StandardCharsets.UTF_8)
    )
} as OutputStreamCallback)

session.transfer(flowFile, REL_SUCCESS)

