def flowFile = session.get()
if (!flowFile) return

try {
    // --- Đọc nội dung ---
    String content = ''
    session.read(flowFile, { InputStream in ->
        content = Fast.readUtf8NoBom(in)
    } as InputStreamCallback)

    if (content == null || content.trim().isEmpty() || content.trim().equalsIgnoreCase('null')) {
        session.remove(flowFile)
        return
    }

    def json
    try {
        json = new JsonSlurper().parseText(content)
    } catch (Exception e) {
        session.transfer(flowFile, REL_FAILURE)
        return
    }

    // --- B1: Lọc dữ liệu null/rỗng ---
    json = Fast.clean(json)

    // --- B2: Kiểm tra điều kiện chính ---
    boolean hasUidOrUsername = (json instanceof Map) &&
        ((json.containsKey('uid') && json.uid) || (json.containsKey('username') && json.username))
    boolean hasFollowerIdOrName = (json instanceof Map) &&
        ((json.containsKey('uid_follower') && json.uid_follower) || (json.containsKey('username_follower') && json.username_follower))

    boolean ok = false
    if (hasUidOrUsername && hasFollowerIdOrName) {
        if (json.containsKey('uid') && json.uid) {
            json.uid = json.uid.toString()
        }
        if (json.containsKey('uid_follower') && json.uid_follower) {
            json.uid_follower = json.uid_follower.toString()
        }
        ok = true
    }

    // --- Ghi lại JSON & chuyển ---
    byte[] outBytes = JsonOutput.toJson(json).getBytes(StandardCharsets.UTF_8)
    flowFile = session.write(flowFile, { OutputStream os -> os.write(outBytes) } as OutputStreamCallback)
    session.transfer(flowFile, ok ? REL_SUCCESS : REL_FAILURE)

} catch (Exception e) {
    log.error("ExecuteScript error", e)
    session.transfer(flowFile, REL_FAILURE)
}

