import groovy.json.JsonSlurper
import groovy.json.JsonOutput
import java.nio.charset.StandardCharsets

flowFile = session.get()
if (!flowFile) return

def sanitizeJson(value) {
    if (value == null) {
        return null
    }

    if (value instanceof Map) {
        return value.findAll { k, v ->
            v != null &&
            !(v instanceof Collection && v.isEmpty()) &&
            !(v instanceof Map && v.isEmpty()) &&
            !(v instanceof String && v.trim().isEmpty())
        }.collectEntries { k, v ->
            [(k): sanitizeJson(v)]
        }
    }

    if (value instanceof Collection) {
        return value.collect { sanitizeJson(it) }
            .findAll { it != null &&
                !(it instanceof Collection && it.isEmpty()) &&
                !(it instanceof Map && it.isEmpty()) &&
                !(it instanceof String && it.trim().isEmpty()) }
    }

    return value
}

def asText(value) {
    def text = value?.toString()?.trim()
    return text ? text : null
}

def asNumber(value) {
    if (value == null || value instanceof Number) {
        return value
    }
    def text = value.toString().trim()
    if (!text) {
        return null
    }
    return text.contains('.') ? text.toDouble() : text.toLong()
}

def asDouble(value) {
    def number = asNumber(value)
    return number instanceof Number ? number.doubleValue() : null
}

def asLong(value) {
    def number = asNumber(value)
    return number instanceof Number ? number.longValue() : null
}

def asUrlList(value) {
    if (value == null) {
        return null
    }
    def items = value instanceof Collection ? value : [value]
    def urls = items.collect { asText(it) }.findAll { it }
    return urls ? urls.unique() : null
}

def toShopProduct(raw) {
    if (!(raw instanceof Map)) {
        return null
    }

    def productId = asText(raw.product_id)
    if (!productId) {
        return null
    }

    def imageUrls = asUrlList(raw.image_urls)
    def videoUrls = asUrlList(raw.video_urls)
    def imageUrl = asText(raw.image_url) ?: (imageUrls ? imageUrls[0] : null)
    def videoUrl = asText(raw.video_url) ?: (videoUrls ? videoUrls[0] : null)

    return [
        product_id     : productId,
        title          : asText(raw.title),
        description    : asText(raw.description),
        url            : asText(raw.url),
        sale_price     : asDouble(raw.sale_price),
        origin_price   : asDouble(raw.origin_price),
        price_text     : asText(raw.price_text),
        currency       : asText(raw.currency),
        discount       : asText(raw.discount),
        image_url      : imageUrl,
        image_urls     : imageUrls,
        video_url      : videoUrl,
        video_urls     : videoUrls,
        seller_id      : asText(raw.seller_id),
        shop_name      : asText(raw.shop_name),
        shop_logo_url  : asText(raw.shop_logo_url),
        sold_count     : asLong(raw.sold_count),
        rating_score   : asDouble(raw.rating_score),
        review_count   : asLong(raw.review_count),
        brand_name     : asText(raw.brand_name),
        domain         : asText(raw.domain) ?: 'shop.tiktok.com',
        indexed_time   : asLong(raw.indexed_time) ?: (System.currentTimeMillis() / 1000L)
    ]
}

def unwrapActualResult(value) {
    if (value instanceof String) {
        def text = value.trim()
        if (!text || text == 'null') {
            return []
        }
        return new JsonSlurper().parseText(text)
    }
    return value
}

def collectProducts(node, products) {
    if (node instanceof Collection && !(node instanceof Map)) {
        node.each { collectProducts(it, products) }
        return
    }
    if (!(node instanceof Map)) {
        return
    }

    // Envelope from GetDataService / ParseData: { modelName, actualResult }
    if (node.modelName != null) {
        if (node.modelName.toString() == 'TikTokShopProduct') {
            collectProducts(unwrapActualResult(node.actualResult), products)
        }
        return
    }

    def product = toShopProduct(node)
    if (product) {
        products << product
    }
}

def content = ''
session.read(flowFile, { inputStream ->
    content = new String(inputStream.bytes, StandardCharsets.UTF_8)
} as InputStreamCallback)

if (!content || content.trim() == '' || content.trim() == 'null') {
    session.remove(flowFile)
    return
}

def products = []
collectProducts(new JsonSlurper().parseText(content), products)
def cleaned = sanitizeJson(products)

if (!cleaned) {
    session.remove(flowFile)
    return
}

flowFile = session.write(flowFile, { out ->
    out.write(JsonOutput.toJson(cleaned).getBytes(StandardCharsets.UTF_8))
} as OutputStreamCallback)

