import groovy.json.JsonSlurper
import groovy.json.JsonOutput
import groovy.transform.CompileStatic
import java.nio.charset.StandardCharsets
import org.apache.nifi.processor.io.InputStreamCallback
import org.apache.nifi.processor.io.OutputStreamCallback

@CompileStatic
class Fast {
    static String readUtf8NoBom(InputStream in) {
        byte[] b = in.bytes
        if (b.length >= 3 && (b[0] & 0xFF) == 0xEF && (b[1] & 0xFF) == 0xBB && (b[2] & 0xFF) == 0xBF) {
            return new String(b, 3, b.length - 3, StandardCharsets.UTF_8)
        }
        String s = new String(b, StandardCharsets.UTF_8)
        return (s.length() > 0 && s.charAt(0) == '\uFEFF' as char) ? s.substring(1) : s
    }

    static long toLongSafe(Object v) {
        if (v == null) return 0L
        if (v instanceof Number) return ((Number) v).longValue()
        String s = v.toString().trim()
        if (s.isEmpty()) return 0L
        try { return Long.parseLong(s) } catch (Exception ignore) { return 0L }
    }

    static boolean notEmpty(Object v) {
        if (v == null) return false
        if (v instanceof Collection) return !((Collection) v).isEmpty()
        return true
    }

    // filter null & collection rỗng (đệ quy)
    static Object clean(Object in) {
        if (in instanceof Map) {
            Map m = (Map) in
            Map out = new LinkedHashMap(m.size())
            for (def e : m.entrySet()) {
                Object cv = clean(e.value)
                if (cv != null && notEmpty(cv)) out.put(String.valueOf(e.key), cv)
            }
            return out
        } else if (in instanceof Collection) {
            List lst = new ArrayList(((Collection) in).size())
            for (Object it : (Collection) in) {
                Object cv = clean(it)
                if (cv != null && notEmpty(cv)) lst.add(cv)
            }
            return lst
        } else {
            return in
        }
    }
}

final String[] REACTION_KEYS = [
        "total_angry","total_dislike","total_favorite",
        "total_haha","total_like","total_love","total_rate","total_sad","total_wow"
] as String[]

def flowFile = session.get()
if (!flowFile) return

String content = ''
session.read(flowFile, { InputStream in ->
    content = Fast.readUtf8NoBom(in)
} as InputStreamCallback)

if (content == null || content.trim().isEmpty() || content.trim().equalsIgnoreCase('null')) {
    session.remove(flowFile)
    return
}

def sl = new JsonSlurper()
def root
try {
    root = sl.parseText(content)
} catch (Exception e) {
    // dữ liệu hỏng
    session.transfer(flowFile, REL_FAILURE)
    return
}

// Chuẩn hoá thành list để xử lý
List items = (root instanceof List) ? (List) root : [root]

List result = new ArrayList(items.size())
for (Object obj : items) {
    if (!(obj instanceof Map)) continue
    Map item = (Map) obj

    // giữ lại khi đủ 3 field: post_id, domain, url
    if (!(item.containsKey('post_id') && item.containsKey('domain') && item.containsKey('url'))) continue
    if (item.get('post_id') == null || item.get('domain') == null || item.get('url') == null) continue

    // nếu tồn tại actor_usertype và == 0 thì xoá field, không bỏ bản ghi
    def actorUserType = item.get('actor_usertype')
    if (actorUserType != null && Fast.toLongSafe(actorUserType) == 0L) {
        item.remove('actor_usertype')
    }

    // normalize id
    if (item.containsKey('actor_id') && item.get('actor_id') != null) {
        item.put('actor_id', String.valueOf(item.get('actor_id')))
    }
    item.put('post_id', String.valueOf(item.get('post_id')))

    // tính total_reaction nhanh
    long sum = 0L
    for (String k : REACTION_KEYS) sum += Fast.toLongSafe(item.get(k))
    long existed = Fast.toLongSafe(item.get('total_reaction'))
    if (sum > existed) item.put('total_reaction', sum)

    // crawlers
    def crawlers = item.get('crawlers')
    if (crawlers instanceof Collection) {
        ((Collection) crawlers).add("Icomm.Nifi.Parser")
    } else {
        item.put('crawlers', ["Icomm.Nifi.Parser"])
    }

        def transcriptTexts = item.get('attachment_transcript_texts')
    if (transcriptTexts != null) {

        String regexToRemove = "(?i)(Có thể là (đồ họa|hình minh họa|hình ảnh) về|Có thể là hình vẽ ngẫu hứng( về)?|Không có mô tả ảnh\\.|No photo description available\\.|May be an? (graphic|illustration|image) of|May be art of)\\s*";
        if (transcriptTexts instanceof Collection) {
            List newTranscripts = new ArrayList(((Collection) transcriptTexts).size())
            for (Object t : (Collection) transcriptTexts) {
                if (t instanceof String) {
                    String s = ((String) t)
                                .replaceAll(regexToRemove, "") 
                                .replaceAll("(?i)văn bản cho biết", "văn bản")
                                .replaceAll("(?i)text that says", "text")
                                .trim()
                    newTranscripts.add(s) 
                } else {
                    newTranscripts.add(t)
                }
            }
            item.put('attachment_transcript_texts', newTranscripts)

        } else if (transcriptTexts instanceof String) {
            String s = ((String) transcriptTexts)
                            .replaceAll(regexToRemove, "")
                            .replaceAll("(?i)văn bản cho biết", "văn bản")
                            .replaceAll("(?i)text that says", "text")
                            .trim()
            item.put('attachment_transcript_texts', s)
        }
    }

    // dọn rác null/empty
    result.add(Fast.clean(item))
}

// ghi kết quả
byte[] outBytes = JsonOutput.toJson(result).getBytes(StandardCharsets.UTF_8)
flowFile = session.write(flowFile, { OutputStream os -> os.write(outBytes) } as OutputStreamCallback)

if (!result.isEmpty()) {
    session.transfer(flowFile, REL_SUCCESS)
} else {
    session.transfer(flowFile, REL_FAILURE)
}

