import groovy.json.JsonSlurper
import groovy.json.JsonOutput
import groovy.transform.CompileStatic
import java.nio.charset.StandardCharsets
import java.time.LocalDate
import java.time.format.DateTimeFormatter
import org.apache.nifi.processor.io.InputStreamCallback
import org.apache.nifi.processor.io.OutputStreamCallback

@CompileStatic
class Utils {
    static final DateTimeFormatter DATE_FMT = DateTimeFormatter.ofPattern('yyyy-MM-dd')

    static String readUtf8NoBom(InputStream inputStream) {
        byte[] b = inputStream.bytes
        if (b.length >= 3 && (b[0] & 0xFF) == 0xEF && (b[1] & 0xFF) == 0xBB && (b[2] & 0xFF) == 0xBF) {
            return new String(b, 3, b.length - 3, StandardCharsets.UTF_8)
        }
        String s = new String(b, StandardCharsets.UTF_8)
        return (s && s.charAt(0) == '\uFEFF' as char) ? s.substring(1) : s
    }

    static boolean notEmpty(Object v) {
        if (v == null) return false
        if (v instanceof Collection) return !((Collection) v).isEmpty()
        if (v instanceof CharSequence) return v.toString().trim().length() > 0
        return true
    }

    static Object clean(Object node) {
        if (node instanceof Map) {
            Map m = (Map) node
            Map out = new LinkedHashMap(m.size())
            for (def e : m.entrySet()) {
                Object cv = clean(e.value)
                if (cv != null && notEmpty(cv)) out.put(String.valueOf(e.key), cv)
            }
            return out
        } else if (node instanceof Collection) {
            List lst = new ArrayList(((Collection) node).size())
            for (Object it : (Collection) node) {
                Object cv = clean(it)
                if (cv != null && notEmpty(cv)) lst.add(cv)
            }
            return lst
        } else if (node instanceof CharSequence) {
            String s = node.toString().trim()
            return s.length() > 0 ? s : null
        } else {
            return node
        }
    }

    static String str(Map m, String... keys) {
        if (m == null || keys == null) return null
        for (String k : keys) {
            Object v = m.get(k)
            if (v == null) continue
            String s = v.toString().trim()
            if (s.length() > 0) return s
        }
        return null
    }

    static Object first(Map m, String... keys) {
        if (m == null || keys == null) return null
        for (String k : keys) {
            if (m.containsKey(k) && m.get(k) != null) return m.get(k)
        }
        return null
    }

    static String toDate(Object v) {
        if (v == null) return null
        String s = v.toString().trim()
        if (s.length() == 0) return null
        if (s.length() >= 10) {
            try {
                return LocalDate.parse(s.substring(0, 10), DATE_FMT).format(DATE_FMT)
            } catch (Exception ignored) {
            }
        }
        return s
    }

    static List toStringList(Object v) {
        if (v == null) return null
        List out = new ArrayList()
        if (v instanceof Collection) {
            for (Object it : (Collection) v) {
                if (it == null) continue
                String s = it.toString().trim()
                if (s.length() > 0) out.add(s)
            }
        } else {
            String s = v.toString().trim()
            if (s.length() > 0) out.add(s)
        }
        return out
    }

    static Map toParty(Map m) {
        if (m == null) return null
        Map c = new LinkedHashMap()
        String countryCode = str(m, 'CountryCode', 'country_code', 'country')
        String name = str(m, 'Name', 'name')
        String address = str(m, 'Address', 'address')
        if (countryCode) c.put('CountryCode', countryCode)
        if (name) c.put('Name', name)
        if (address) c.put('Address', address)
        return c.isEmpty() ? null : c
    }

    static List toParties(Object v) {
        if (v == null) return null
        List out = new ArrayList()
        if (v instanceof Collection) {
            for (Object it : (Collection) v) {
                if (it instanceof Map) {
                    Map party = toParty((Map) it)
                    if (party != null) out.add(party)
                } else if (it != null) {
                    String name = it.toString().trim()
                    if (name.length() > 0) {
                        Map party = new LinkedHashMap()
                        party.put('Name', name)
                        out.add(party)
                    }
                }
            }
        } else if (v instanceof Map) {
            Map party = toParty((Map) v)
            if (party != null) out.add(party)
        } else {
            String name = v.toString().trim()
            if (name.length() > 0) {
                Map party = new LinkedHashMap()
                party.put('Name', name)
                out.add(party)
            }
        }
        return out
    }

    static List toPriorities(Object v) {
        if (!(v instanceof Collection)) return null
        List out = new ArrayList()
        for (Object it : (Collection) v) {
            if (!(it instanceof Map)) continue
            Map m = (Map) it
            Map c = new LinkedHashMap()
            String number = str(m, 'Number', 'number')
            String date = toDate(first(m, 'Date', 'date'))
            String country = str(m, 'Country', 'country')
            if (number) c.put('Number', number)
            if (date) c.put('Date', date)
            if (country) c.put('Country', country)
            if (!c.isEmpty()) out.add(c)
        }
        return out
    }

    static List toEvents(Object v) {
        if (!(v instanceof Collection)) return null
        List out = new ArrayList()
        for (Object it : (Collection) v) {
            if (!(it instanceof Map)) continue
            Map m = (Map) it
            Map c = new LinkedHashMap()
            String process = str(m, 'Process', 'process')
            String date = toDate(first(m, 'Date', 'date'))
            String status = str(m, 'Status', 'status')
            if (process) c.put('Process', process)
            if (date) c.put('Date', date)
            if (status) c.put('Status', status)
            if (!c.isEmpty()) out.add(c)
        }
        return out
    }

    static void putIf(Map item, String key, Object val) {
        if (val != null && notEmpty(val)) item.put(key, val)
    }

    /**
     * Chuẩn hóa map đầu vào về bộ key parser (PatentRecord):
     * - Id, ApplicationType, ApplicationKind, GrantNumber, GrantDate, Status, ExpiredDate
     * - ApplicationNumber, ApplicationDate, PublicationNumber, GazetteNumber, PublicationKind, PublicationDate
     * - PctApplicationNumber, PctApplicationDate, PctPublicationNumber, PctPublicationDate, NationalPhaseDate
     * - Title, Abstract, Priorities, IpcClassifications, Applicants, Inventors, Representatives
     * - Citations, Events, DrawingUrls
     */
    static Map toCanonicalPatentMap(Map m) {
        if (m == null) return null
        Map c = new LinkedHashMap()
        c.put('Id', str(m, 'Id', 'id'))
        c.put('ApplicationType', str(m, 'ApplicationType', 'application_type'))
        c.put('ApplicationKind', str(m, 'ApplicationKind', 'application_kind'))
        c.put('GrantNumber', str(m, 'GrantNumber', 'grant_number'))
        c.put('GrantDate', toDate(first(m, 'GrantDate', 'grant_date')))
        c.put('Status', str(m, 'Status', 'status'))
        c.put('ExpiredDate', toDate(first(m, 'ExpiredDate', 'expired_date')))
        c.put('ApplicationNumber', str(m, 'ApplicationNumber', 'application_number'))
        c.put('ApplicationDate', toDate(first(m, 'ApplicationDate', 'application_date')))
        c.put('PublicationNumber', str(m, 'PublicationNumber', 'publication_number'))
        c.put('GazetteNumber', str(m, 'GazetteNumber', 'gazette_number'))
        c.put('PublicationKind', str(m, 'PublicationKind', 'publication_kind'))
        c.put('PublicationDate', toDate(first(m, 'PublicationDate', 'publication_date')))
        c.put('PctApplicationNumber', str(m, 'PctApplicationNumber', 'pct_application_number'))
        c.put('PctApplicationDate', toDate(first(m, 'PctApplicationDate', 'pct_application_date')))
        c.put('PctPublicationNumber', str(m, 'PctPublicationNumber', 'pct_publication_number'))
        c.put('PctPublicationDate', toDate(first(m, 'PctPublicationDate', 'pct_publication_date')))
        c.put('NationalPhaseDate', toDate(first(m, 'NationalPhaseDate', 'national_phase_date')))
        c.put('Title', str(m, 'Title', 'title', 'Name', 'name'))
        c.put('Abstract', str(m, 'Abstract', 'abstract'))
        List priorities = toPriorities(first(m, 'Priorities', 'priorities'))
        if (priorities != null) c.put('Priorities', priorities)
        List ipc = toStringList(first(m, 'IpcClassifications', 'ipc_classifications'))
        if (ipc != null) c.put('IpcClassifications', ipc)
        List applicants = toParties(first(m, 'Applicants', 'applicants'))
        if (applicants != null) c.put('Applicants', applicants)
        List inventors = toParties(first(m, 'Inventors', 'inventors'))
        if (inventors != null) c.put('Inventors', inventors)
        List representatives = toParties(first(m, 'Representatives', 'representatives'))
        if (representatives != null) c.put('Representatives', representatives)
        List citations = toStringList(first(m, 'Citations', 'citations'))
        if (citations != null) c.put('Citations', citations)
        List events = toEvents(first(m, 'Events', 'events'))
        if (events != null) c.put('Events', events)
        List drawings = toStringList(first(m, 'DrawingUrls', 'drawing_urls'))
        if (drawings != null) c.put('DrawingUrls', drawings)
        return c
    }

    /** Đủ dữ liệu để xuất bản ghi: có Id hoặc ApplicationNumber (uniqueId của PatentRecord). */
    static boolean isValidPatentInput(Map m) {
        if (m == null) return false
        Map c = toCanonicalPatentMap(m)
        def id = c.get('Id')?.toString()?.trim()
        def applicationNumber = c.get('ApplicationNumber')?.toString()?.trim()
        return (id as boolean) || (applicationNumber as boolean)
    }

    static boolean isValidPatentItem(Object item) {
        if (item instanceof Map) return isValidPatentInput((Map) item)
        return false
    }

    static Map normalizeToOutput(Map m) {
        Map c = toCanonicalPatentMap(m)
        Map item = new LinkedHashMap()
        putIf(item, 'Id', c.get('Id'))
        putIf(item, 'ApplicationType', c.get('ApplicationType'))
        putIf(item, 'ApplicationKind', c.get('ApplicationKind'))
        putIf(item, 'GrantNumber', c.get('GrantNumber'))
        putIf(item, 'GrantDate', c.get('GrantDate'))
        putIf(item, 'Status', c.get('Status'))
        putIf(item, 'ExpiredDate', c.get('ExpiredDate'))
        putIf(item, 'ApplicationNumber', c.get('ApplicationNumber'))
        putIf(item, 'ApplicationDate', c.get('ApplicationDate'))
        putIf(item, 'PublicationNumber', c.get('PublicationNumber'))
        putIf(item, 'GazetteNumber', c.get('GazetteNumber'))
        putIf(item, 'PublicationKind', c.get('PublicationKind'))
        putIf(item, 'PublicationDate', c.get('PublicationDate'))
        putIf(item, 'PctApplicationNumber', c.get('PctApplicationNumber'))
        putIf(item, 'PctApplicationDate', c.get('PctApplicationDate'))
        putIf(item, 'PctPublicationNumber', c.get('PctPublicationNumber'))
        putIf(item, 'PctPublicationDate', c.get('PctPublicationDate'))
        putIf(item, 'NationalPhaseDate', c.get('NationalPhaseDate'))
        putIf(item, 'Title', c.get('Title'))
        putIf(item, 'Abstract', c.get('Abstract'))
        putIf(item, 'Priorities', c.get('Priorities'))
        putIf(item, 'IpcClassifications', c.get('IpcClassifications'))
        putIf(item, 'Applicants', c.get('Applicants'))
        putIf(item, 'Inventors', c.get('Inventors'))
        putIf(item, 'Representatives', c.get('Representatives'))
        putIf(item, 'Citations', c.get('Citations'))
        putIf(item, 'Events', c.get('Events'))
        putIf(item, 'DrawingUrls', c.get('DrawingUrls'))
        return item
    }

    /** Nhận 1 record, mảng record, hoặc wrapper PatentSearchResult { Rows / rows }. */
    static List extractRecords(Object json) {
        if (json instanceof List) return (List) json
        if (json instanceof Map) {
            Map m = (Map) json
            Object rows = m.get('Rows')
            if (rows == null) rows = m.get('rows')
            if (rows instanceof List) return (List) rows
            return [m]
        }
        return new ArrayList()
    }
}

def flowFile = session.get()
if (!flowFile) return

try {
    String content = ''
    session.read(flowFile, { InputStream inputStream ->
        content = Utils.readUtf8NoBom(inputStream)
    } as InputStreamCallback)

    if (content == null || content.trim().isEmpty() || content.trim().equalsIgnoreCase('null')) {
        session.remove(flowFile)
        return
    }

    def json
    try {
        json = new JsonSlurper().parseText(content)
    } catch (Exception e) {
        session.transfer(flowFile, REL_FAILURE)
        return
    }

    json = Utils.clean(json)

    List normalized = new ArrayList()
    List records = Utils.extractRecords(json)
    records.findAll { Utils.isValidPatentItem(it) }.each { Map m ->
        normalized.add(Utils.normalizeToOutput(m))
    }

    if (normalized.isEmpty()) {
        session.transfer(flowFile, REL_FAILURE)
        return
    }

    byte[] outBytes = JsonOutput.toJson(normalized).getBytes(StandardCharsets.UTF_8)
    flowFile = session.write(flowFile, { OutputStream os -> os.write(outBytes) } as OutputStreamCallback)
    flowFile = session.putAttribute(flowFile, 'record.count', String.valueOf(normalized.size()))
    session.transfer(flowFile, REL_SUCCESS)

} catch (Exception e) {
    log.error("ExecuteScript error", e)
    session.transfer(flowFile, REL_FAILURE)
}

