        if (b.length >= 3 && (b[0] & 0xFF) == 0xEF && (b[1] & 0xFF) == 0xBB && (b[2] & 0xFF) == 0xBF) {
            return new String(b, 3, b.length - 3, StandardCharsets.UTF_8)
        }
        String s = new String(b, StandardCharsets.UTF_8)
        return (s && s.charAt(0) == '\uFEFF' as char) ? s.substring(1) : s
    }

    static boolean notEmpty(Object v) {
        if (v == null) return false
        if (v instanceof Collection) return !((Collection) v).isEmpty()
        if (v instanceof CharSequence) return v.toString().trim().length() > 0
        return true
    }

    static Object clean(Object node) {
        if (node instanceof Map) {
            Map m = (Map) node
            Map out = new LinkedHashMap(m.size())
            for (def e : m.entrySet()) {
                Object cv = clean(e.value)
                if (cv != null && notEmpty(cv)) out.put(String.valueOf(e.key), cv)
            }
            return out
        } else if (node instanceof Collection) {
            List lst = new ArrayList(((Collection) node).size())
            for (Object it : (Collection) node) {
                Object cv = clean(it)
                if (cv != null && notEmpty(cv)) lst.add(cv)
            }
            return lst
        } else if (node instanceof CharSequence) {
            String s = node.toString().trim()
            return s.length() > 0 ? s : null
        } else {
            return node
        }
    }

    static String str(Map m, String... keys) {
        if (m == null || keys == null) return null
        for (String k : keys) {
            Object v = m.get(k)
            if (v == null) continue
            String s = v.toString().trim()
            if (s.length() > 0) return s
        }
        return null
    }

    static String toDate(Object v) {
        if (v == null) return null
        String s = v.toString().trim()
        if (s.length() == 0) return null
        if (s.length() >= 10) {
            try {
                return LocalDate.parse(s.substring(0, 10), DATE_FMT).format(DATE_FMT)
            } catch (Exception ignored) {
            }
        }
        return s
    }

    static List toProductServiceClasses(Object v) {
        if (!(v instanceof Collection)) return null
        List out = new ArrayList()
        for (Object it : (Collection) v) {
            if (!(it instanceof Map)) continue
            Map m = (Map) it
            Map c = new LinkedHashMap()
            String groupName = str(m, 'GroupName', 'group_name', 'code')
            String description = str(m, 'Description', 'description')
            if (groupName) c.put('GroupName', groupName)
            if (description) c.put('Description', description)
            if (!c.isEmpty()) out.add(c)
        }
        return out
    }

    static void putIf(Map item, String key, Object val) {
        if (val != null && notEmpty(val)) item.put(key, val)
    }

    /**
     * Chuẩn hóa map đầu vào về bộ key parser (TrademarkRecord):
     * - Id, Name, Status, ImageUrl, ApplicationDate, CertificateNumber, PublicationNumber
     * - CertificateDate, ExpiredDate, OwnerName, OwnerAddress, RepresentName, RepresentAddress
     * - ProductServiceClasses [{ GroupName, Description }]
     * Chấp nhận thêm schema snake_case / raw API: id, image_url, logo, application_date, nices, ...
     */
    static Map toCanonicalTrademarkMap(Map m) {
        if (m == null) return null
        Map c = new LinkedHashMap()
        c.put('Id', str(m, 'Id', 'id', 'application_number'))
        c.put('Name', str(m, 'Name', 'name'))
        c.put('Status', str(m, 'Status', 'status'))
        c.put('ImageUrl', str(m, 'ImageUrl', 'image_url', 'logo'))
        c.put('ApplicationDate', toDate(m.containsKey('ApplicationDate') ? m.get('ApplicationDate') : (m.containsKey('application_date') ? m.get('application_date') : null)))
        c.put('CertificateNumber', str(m, 'CertificateNumber', 'certificate_number'))
        c.put('PublicationNumber', str(m, 'PublicationNumber', 'publication_number'))
        c.put('CertificateDate', toDate(m.containsKey('CertificateDate') ? m.get('CertificateDate') : (m.containsKey('certificate_date') ? m.get('certificate_date') : null)))
        c.put('ExpiredDate', toDate(m.containsKey('ExpiredDate') ? m.get('ExpiredDate') : (m.containsKey('expired_date') ? m.get('expired_date') : null)))
        c.put('OwnerName', str(m, 'OwnerName', 'owner_name'))
        c.put('OwnerAddress', str(m, 'OwnerAddress', 'owner_address'))
        c.put('RepresentName', str(m, 'RepresentName', 'represent_name'))
        c.put('RepresentAddress', str(m, 'RepresentAddress', 'represent_address'))
        Object classesRaw = m.get('ProductServiceClasses')
        if (classesRaw == null) classesRaw = m.get('product_service_classes')
        if (classesRaw == null) classesRaw = m.get('nices')
        List classes = toProductServiceClasses(classesRaw)
        if (classes != null) c.put('ProductServiceClasses', classes)
        return c
    }

    /** Đủ dữ liệu để xuất bản ghi: có Id (uniqueId của TrademarkRecord). */
    static boolean isValidTrademarkInput(Map m) {
        if (m == null) return false
        Map c = toCanonicalTrademarkMap(m)
        def id = c.get('Id')?.toString()?.trim()
        return id as boolean
    }

    static boolean isValidTrademarkItem(Object item) {
        if (item instanceof Map) return isValidTrademarkInput((Map) item)
        return false
    }

    static Map normalizeToOutput(Map m) {
        Map c = toCanonicalTrademarkMap(m)
        Map item = new LinkedHashMap()
        putIf(item, 'Id', c.get('Id'))
        putIf(item, 'Name', c.get('Name'))
        putIf(item, 'Status', c.get('Status'))
        putIf(item, 'ImageUrl', c.get('ImageUrl'))
        putIf(item, 'ApplicationDate', c.get('ApplicationDate'))
        putIf(item, 'CertificateNumber', c.get('CertificateNumber'))
        putIf(item, 'PublicationNumber', c.get('PublicationNumber'))
        putIf(item, 'CertificateDate', c.get('CertificateDate'))
        putIf(item, 'ExpiredDate', c.get('ExpiredDate'))
        putIf(item, 'OwnerName', c.get('OwnerName'))
        putIf(item, 'OwnerAddress', c.get('OwnerAddress'))
        putIf(item, 'RepresentName', c.get('RepresentName'))
        putIf(item, 'RepresentAddress', c.get('RepresentAddress'))
        putIf(item, 'ProductServiceClasses', c.get('ProductServiceClasses'))
        return item
    }

    /** Nhận 1 record, mảng record, hoặc wrapper TrademarkSearchResult { Rows / rows }. */
    static List extractRecords(Object json) {
        if (json instanceof List) return (List) json
        if (json instanceof Map) {
            Map m = (Map) json
            Object rows = m.get('Rows')
            if (rows == null) rows = m.get('rows')
            if (rows instanceof List) return (List) rows
            return [m]
        }
        return new ArrayList()
    }
}

def flowFile = session.get()
if (!flowFile) return

try {
    String content = ''
    session.read(flowFile, { InputStream inputStream ->
        content = Utils.readUtf8NoBom(inputStream)
    } as InputStreamCallback)

    if (content == null || content.trim().isEmpty() || content.trim().equalsIgnoreCase('null')) {
        session.remove(flowFile)
        return
    }

    def json
    try {
        json = new JsonSlurper().parseText(content)
    } catch (Exception e) {
        session.transfer(flowFile, REL_FAILURE)
        return
    }

    json = Utils.clean(json)

    List normalized = new ArrayList()
    List records = Utils.extractRecords(json)
    records.findAll { Utils.isValidTrademarkItem(it) }.each { Map m ->
        normalized.add(Utils.normalizeToOutput(m))
    }

    if (normalized.isEmpty()) {
        session.transfer(flowFile, REL_FAILURE)
        return
    }

    byte[] outBytes = JsonOutput.toJson(normalized).getBytes(StandardCharsets.UTF_8)
