import groovy.json.JsonSlurper
import groovy.json.JsonOutput
import groovy.transform.CompileStatic
import java.nio.charset.StandardCharsets
import org.apache.nifi.processor.io.InputStreamCallback
import org.apache.nifi.processor.io.OutputStreamCallback
import java.net.URI
import java.security.MessageDigest

@CompileStatic
class Utils {
    static String readUtf8NoBom(InputStream in) {
        byte[] b = in.bytes
        if (b.length >= 3 && (b[0] & 0xFF) == 0xEF && (b[1] & 0xFF) == 0xBB && (b[2] & 0xFF) == 0xBF) {
            return new String(b, 3, b.length - 3, StandardCharsets.UTF_8)
        }
        String s = new String(b, StandardCharsets.UTF_8)
        return (s.length() > 0 && s.charAt(0) == '\uFEFF' as char) ? s.substring(1) : s
    }
    static boolean notEmpty(Object v) {
        if (v == null) return false
        if (v instanceof Collection) return !((Collection) v).isEmpty()
        return true
    }
    static Object clean(Object in) {
        if (in instanceof Map) {
            Map m = (Map) in
            Map out = new LinkedHashMap(m.size())
            for (def e : m.entrySet()) {
                Object cv = clean(e.value)
                if (cv != null && notEmpty(cv)) out.put(String.valueOf(e.key), cv)
            }
            return out
        } else if (in instanceof Collection) {
            List lst = new ArrayList(((Collection) in).size())
            for (Object it : (Collection) in) {
                Object cv = clean(it)
                if (cv != null && notEmpty(cv)) lst.add(cv)
            }
            return lst
        } else return in
    }
    static boolean hasText(Object v) { v != null && v.toString().trim().length() > 0 }
    static String md5Path(String url) {
        if (url == null) return null
        try {
            URI u = new URI(url)
            String path = u.getPath() ?: ""
            byte[] hash = MessageDigest.getInstance("MD5").digest(path.getBytes(StandardCharsets.UTF_8))
            StringBuilder sb = new StringBuilder(hash.length * 2)
            for (byte b : hash) sb.append(String.format("%02x", b))
            return sb.toString()
        } catch (Exception e) { return null }
    }
}

def parent = session.get()
if (!parent) return

List created = []
try {
    // Read + strip BOM
    String content = ''
    session.read(parent, { InputStream in -> content = Utils.readUtf8NoBom(in) } as InputStreamCallback)
    if (content == null || content.trim().isEmpty() || content.trim().equalsIgnoreCase('null')) {
        session.remove(parent); return
    }

    // Parse root
    def root
    try {
        root = new JsonSlurper().parseText(content)
    } catch (Exception e) {
        session.transfer(parent, REL_FAILURE); return
    }

    // ---------- Phần A: Chuẩn hoá post/ad_id -> gói vào 1 FlowFile "success" ----------
    List results = new ArrayList(16)
    def processPost = { Map item ->
        item = (Map) Utils.clean(item)
        if (!(item.containsKey('post_id') && Utils.hasText(item.get('post_id')))) return
        item.put('post_id', String.valueOf(item.get('post_id')))
        if (item.containsKey('ad_id') && Utils.hasText(item.get('ad_id'))) {
            item.put('ad_id', String.valueOf(item.get('ad_id')))
        }
        if (item.containsKey('post_unique_id') && Utils.hasText(item.get('post_unique_id'))) {
            // giữ nguyên logic: post_unique_id ghi đè ad_id
            item.put('ad_id', String.valueOf(item.get('post_unique_id')))
        }
        results.add(item)
    }
    if (root instanceof List) {
        for (Object o : (List) root) if (o instanceof Map) processPost((Map) o)
    } else if (root instanceof Map) {
        processPost((Map) root)
    }

    if (!results.isEmpty()) {
        def ff = session.create(parent)
        ff = session.write(ff, { OutputStream os -> os.write(JsonOutput.toJson(results).getBytes(StandardCharsets.UTF_8)) } as OutputStreamCallback)
        ff = session.putAttribute(ff, 'route', 'ads')
        ff = session.putAttribute(ff, 'mime.type', 'application/json')
        created.add(ff)
        session.transfer(ff, REL_SUCCESS)
    }

    // ---------- Phần B: Trích xuất image/video -> MỖI ITEM 1 FlowFile ----------
    def emitImage = { Map img ->
        img = (Map) Utils.clean(img)
        def ff = session.create(parent)
        ff = session.write(ff, { OutputStream os -> os.write(JsonOutput.toJson(img).getBytes(StandardCharsets.UTF_8)) } as OutputStreamCallback)
        // Set attribute để RouteOnAttribute tẽ ra nhánh "image"
        ff = session.putAttribute(ff, 'route', 'image')
        ff = session.putAttribute(ff, 'mime.type', 'application/json')
        if (img.post_id) ff = session.putAttribute(ff, 'post_id', String.valueOf(img.post_id))
        if (img.image_id) ff = session.putAttribute(ff, 'image_id', String.valueOf(img.image_id))
        created.add(ff)
        session.transfer(ff, REL_SUCCESS)
    }
    def emitVideo = { Map vid ->
        vid = (Map) Utils.clean(vid)
        def ff = session.create(parent)
        ff = session.write(ff, { OutputStream os -> os.write(JsonOutput.toJson(vid).getBytes(StandardCharsets.UTF_8)) } as OutputStreamCallback)
        // Set attribute để RouteOnAttribute tẽ ra nhánh "video"
        ff = session.putAttribute(ff, 'route', 'video')
        ff = session.putAttribute(ff, 'mime.type', 'application/json')
        if (vid.post_id) ff = session.putAttribute(ff, 'post_id', String.valueOf(vid.post_id))
        if (vid.video_id) ff = session.putAttribute(ff, 'video_id', String.valueOf(vid.video_id))
        created.add(ff)
        session.transfer(ff, REL_SUCCESS)
    }

    def scanAttachments = { Map item ->
        def post = (item.get('post') instanceof Map) ? (Map) item.get('post') : null
        if (post == null) return
        def atts = post.get('attachments')
        if (!(atts instanceof Collection) || ((Collection) atts).isEmpty()) return

        for (Object a : (Collection) atts) {
            if (!(a instanceof Map)) continue
            Map att = (Map) a
            String type = att.get('type')?.toString()?.toLowerCase()

            // Ảnh → phát per-item
            if (type?.contains('photo') || type?.contains('image')) {
                String imgUrl = att.get('image_url')?.toString()
                Map img = new LinkedHashMap()
                img.put('post_id'           , post.get('post_id') ?: Utils.md5Path(item.get('post_id')?.toString()))
                img.put('post_url'          , post.get('url'))
                img.put('type'              , 'post_image')
                img.put('platform'          , post.get('domain'))
                img.put('image_id'          , (imgUrl != null ? Utils.md5Path(imgUrl) : null))
                img.put('image_download_url', imgUrl)
                img.put('content'           , post.get('message'))
                img.put('actor_name'        , ((post.get('profile') instanceof Map) ? ((Map)post.get('profile')).get('name') : null))
                img.put('source_type'       , 6)
                if (post.containsKey('actor_id'))  img.put('actor_id' , post.get('actor_id'))
                if (post.containsKey('actor_url')) img.put('actor_url', post.get('actor_url'))
                emitImage(img)
            }

            // Video → phát per-item
            if (type?.contains('video')) {
                String vidUrl = att.get('video_url')?.toString()
                Map vid = new LinkedHashMap()
                vid.put('post_id'           , post.get('post_id') ?: Utils.md5Path(item.get('post_id')?.toString()))
                vid.put('post_url'          , post.get('url'))
                vid.put('type'              , 'post_video')
                vid.put('platform'          , post.get('domain'))
                vid.put('video_id'          , (vidUrl != null ? Utils.md5Path(vidUrl) : null))
                vid.put('video_download_url', vidUrl)
                vid.put('content'           , post.get('message'))
                vid.put('actor_name'        , ((post.get('profile') instanceof Map) ? ((Map)post.get('profile')).get('name') : null))
                vid.put('source_type'       , 6)
                if (post.containsKey('actor_id'))  vid.put('actor_id' , post.get('actor_id'))
                if (post.containsKey('actor_url')) vid.put('actor_url', post.get('actor_url'))
                emitVideo(vid)
            }
        }
    }

    if (root instanceof List) {
        for (Object o : (List) root) if (o instanceof Map) scanAttachments((Map) o)
    } else if (root instanceof Map) {
        scanAttachments((Map) root)
    }

    // Kết thúc: nếu không tạo được gì → parent -> failure; ngược lại remove parent
    if (created.isEmpty()) session.transfer(parent, REL_FAILURE)
    else session.remove(parent)

} catch (Exception e) {
    log.error("ExecuteScript error", e)
    if (created.isEmpty()) session.transfer(parent, REL_FAILURE)
    else session.remove(parent)
}

import groovy.json.JsonSlurper
import groovy.json.JsonOutput
import java.nio.charset.StandardCharsets

flowFile = session.get()
if (!flowFile) return

def sanitizeJson(value) {
    if (value == null) {
        return null
    }

    if (value instanceof Map) {
        return value.findAll { k, v ->
            v != null &&
            !(v instanceof Collection && v.isEmpty()) &&
            !(v instanceof Map && v.isEmpty()) &&
            !(v instanceof String && v.trim().isEmpty())
        }.collectEntries { k, v ->
            [(k): sanitizeJson(v)]
        }
    }

    if (value instanceof Collection) {
        return value.collect { sanitizeJson(it) }
            .findAll { it != null &&
                !(it instanceof Collection && it.isEmpty()) &&
                !(it instanceof Map && it.isEmpty()) &&
                !(it instanceof String && it.trim().isEmpty()) }
    }

    return value
}

def asText(value) {
    def text = value?.toString()?.trim()
    return text ? text : null
}

def asNumber(value) {
    if (value == null || value instanceof Number) {
        return value
    }
    def text = value.toString().trim()
    if (!text) {
        return null
    }
    return text.contains('.') ? text.toDouble() : text.toLong()
}

def asInt(value) {
    def number = asNumber(value)
    return number instanceof Number ? number.intValue() : null
}

def asBoolean(value) {
    if (value == null || value instanceof Boolean) {
        return value
    }
    def text = value.toString().trim().toLowerCase()
    if (text == 'true') {
        return true
    }
    if (text == 'false') {
        return false
    }
    return null
}

def toShopCategory(raw) {
    if (!(raw instanceof Map)) {
        return null
    }

    def categoryId = asText(raw.category_id)
    if (!categoryId) {
        return null
    }

    return [
        category_id         : categoryId,
        category_name       : asText(raw.category_name),
        category_name_en    : asText(raw.category_name_en),
        category_level      : asInt(raw.category_level),
        is_leaf             : asBoolean(raw.is_leaf),
        parent_category_id  : asText(raw.parent_category_id),
        image_url           : asText(raw.image_url),
        url                 : asText(raw.url),
        domain              : asText(raw.domain) ?: 'shop.tiktok.com'
    ]
}

def unwrapActualResult(value) {
    if (value instanceof String) {
        def text = value.trim()
        if (!text || text == 'null') {
            return []
        }
        return new JsonSlurper().parseText(text)
    }
    return value
}

def collectCategories(node, categories) {
    if (node instanceof Collection && !(node instanceof Map)) {
        node.each { collectCategories(it, categories) }
        return
    }
    if (!(node instanceof Map)) {
        return
    }

    if (node.modelName?.toString() == 'TikTokShopCategory') {
        collectCategories(unwrapActualResult(node.actualResult), categories)
        return
    }

    def category = toShopCategory(node)
    if (category) {
        categories << category
    }
}

def content = ''
session.read(flowFile, { inputStream ->
    content = new String(inputStream.bytes, StandardCharsets.UTF_8)
} as InputStreamCallback)

if (!content || content.trim() == '' || content.trim() == 'null') {
    session.remove(flowFile)
    return
}

def categories = []
collectCategories(new JsonSlurper().parseText(content), categories)
def cleaned = sanitizeJson(categories)

if (!cleaned) {
    session.remove(flowFile)
    return
}

flowFile = session.write(flowFile, { out ->
    out.write(JsonOutput.toJson(cleaned).getBytes(StandardCharsets.UTF_8))
} as OutputStreamCallback)

session.transfer(flowFile, REL_SUCCESS)

