import groovy.json.JsonSlurper
import groovy.json.JsonOutput
import java.nio.charset.StandardCharsets
import java.time.Instant

flowFile = session.get()
if (!flowFile) return

def sanitizeJson(value) {
    if (value == null) {
        return null
    }

    if (value instanceof Map) {
        return value.findAll { k, v ->
            v != null &&
            !(v instanceof Collection && v.isEmpty()) &&
            !(v instanceof Map && v.isEmpty()) &&
            !(v instanceof String && v.trim().isEmpty())
        }.collectEntries { k, v ->
            [(k): sanitizeJson(v)]
        }
    }

    if (value instanceof Collection) {
        return value.collect { sanitizeJson(it) }
            .findAll { it != null &&
                !(it instanceof Collection && it.isEmpty()) &&
                !(it instanceof Map && it.isEmpty()) &&
                !(it instanceof String && it.trim().isEmpty()) }
    }

    return value
}

def asNumber(value) {
    if (value == null || value instanceof Number) {
        return value
    }
    def text = value.toString().trim()
    if (!text) {
        return null
    }
    return text.contains('.') ? text.toDouble() : text.toLong()
}

def asText(value) {
    def text = value?.toString()?.trim()
    return text ? text : null
}

def asStringList(value) {
    if (value instanceof String) {
        def text = value.trim()
        return text ? [text] : null
    }
    if (!(value instanceof Collection) || value instanceof Map) {
        return null
    }
    def items = value.findAll { it != null && it.toString().trim() }.collect { it.toString().trim() }
    return items ? items : null
}

def asUnixSeconds(value) {
    def number = asNumber(value)
    if (!(number instanceof Number)) {
        return null
    }
    long epoch = number.longValue()
    if (epoch >= 1000000000000000L) {
        return (long) (epoch / 1000000L)
    }
    if (epoch >= 1000000000000L) {
        return (long) (epoch / 1000L)
    }
    return epoch
}

def asCreatedTime(raw) {
    def seconds = asUnixSeconds(raw.published_time)
    if (seconds != null) {
        return seconds
    }
    def text = asText(raw.created_time)
    if (!text) {
        return null
    }
    try {
        def normalized = text.endsWith('Z') ? text : "${text}Z"
        return Instant.parse(normalized).epochSecond
    } catch (Exception ignored) {
        return null
    }
}

def firstNumber(Object... values) {
    for (def value : values) {
        def number = asNumber(value)
        if (number instanceof Number) {
            return number
        }
    }
    return null
}

def mapsCidUrl(value) {
    def cid = asText(value)
    if (!cid || !(cid ==~ /\d+/)) {
        return null
    }
    return "https://maps.google.com/?cid=${cid}"
}

def toPost(raw) {
    if (!(raw instanceof Map)) {
        return null
    }

    def reviewId = asText(raw.review_id)
    if (!reviewId) {
        return null
    }

    def reviewer = raw.reviewer instanceof Map ? raw.reviewer : [:]
    def content = asText(raw.content)
    def images = asStringList(raw.image_urls) ?: asStringList(raw.photo)
    def rate = firstNumber(raw.rating, raw.review_star)
    def likes = firstNumber(raw.likes, raw.like_count)

    return [
        id                : "maps.google.com_${reviewId}",
        post_id           : reviewId,
        post_type         : 'review',
        source_type       : 8,
        url               : asText(raw.review_url),
        domain            : 'maps.google.com',
        domain_name       : 'Google Maps',
        shared_domain     : 'google.com',
        actor_id          : asText(reviewer.user_id) ?: asText(raw.user_id),
        actor_name        : asText(reviewer.name) ?: asText(raw.user_name),
        actor_url         : asText(reviewer.profile_url),
        parent_actor_id   : asText(raw.cid),
        parent_actor_url  : mapsCidUrl(raw.cid),
        parent_id         : asText(raw.location_id),
        parent_actor_name : asText(raw.place_name),
        shared_url        : asText(raw.location_url),
        shared_title      : asText(raw.place_name),
        shared_snippet    : asText(raw.place_address),
        message           : content,
        message_raw       : content,
        snippet           : content,
        created_time      : asCreatedTime(raw),
        total_rate        : rate == null ? null : rate.longValue(),
        total_like        : likes == null ? null : likes.longValue(),
        attachment_urls   : images,
        attachment_types  : images ? images.collect { 'image' } : null
    ]
}

def unwrapActualResult(value) {
    if (value instanceof String) {
        def text = value.trim()
        if (!text || text == 'null') {
            return []
        }
        return new JsonSlurper().parseText(text)
    }
    return value
}

def collectReviews(node, posts) {
    if (node instanceof Collection && !(node instanceof Map)) {
        node.each { collectReviews(it, posts) }
        return
    }
    if (!(node instanceof Map)) {
        return
    }

    if (node.modelName?.toString() == 'GoogleMapsReview') {
        collectReviews(unwrapActualResult(node.actualResult), posts)
        return
    }

    def post = toPost(node)
    if (post) {
        posts << post
        return
    }
}

