def asText(value) {
    if (value == null) return null
    def text = value.toString().trim()
    return text ? text : null
}

def asNumber(value) {
    if (value == null || value instanceof Number) {
        return value
    }

    def text = value.toString().trim()
    if (!text) return null

    try {
        return text.contains('.') ?
            new BigDecimal(text) : Long.valueOf(text)
    } catch (Exception ignored) {
        return null
    }
}

def asLong(value) {
    def number = asNumber(value)
    return number instanceof Number ? number.longValue() : null
}

def asDouble(value) {
    def number = asNumber(value)
    return number instanceof Number ? number.doubleValue() : null
}

def asBoolean(value) {
    if (value == null) return null
    if (value instanceof Boolean) return value

    if (value instanceof Number) {
        if (value == 1) return true
        if (value == 0) return false
        return null
    }

    switch (value.toString().trim().toLowerCase()) {
        case 'true':
        case '1':
        case 'yes':
            return true
        case 'false':
        case '0':
        case 'no':
            return false
        default:
            return null
    }
}

def sanitizeJson(value) {
    if (value == null) return null

    if (value instanceof Map) {
        def result = [:]

        value.each { k, v ->
            def cleaned = sanitizeJson(v)

            if (cleaned != null &&
                !(cleaned instanceof Collection && cleaned.isEmpty()) &&
                !(cleaned instanceof Map && cleaned.isEmpty()) &&
                !(cleaned instanceof String && cleaned.trim().isEmpty())) {
                result[k] = cleaned
            }
        }

        return result
    }

    if (value instanceof Collection) {
        return value.collect { sanitizeJson(it) }
                    .findAll { v ->
                        v != null &&
                        !(v instanceof Collection && v.isEmpty()) &&
                        !(v instanceof Map && v.isEmpty()) &&
                        !(v instanceof String && v.trim().isEmpty())
                    }
    }

    return value
}

def toShop(raw) {
    if (!(raw instanceof Map)) return null

    def sellerId = asText(raw.seller_id)

    // seller_id là khóa nhận diện của TikTokShop.
    if (!sellerId) return null

    return [
        seller_id       : sellerId,
        shop_name       : asText(raw.shop_name),
        shop_username   : asText(raw.shop_username),
        shop_logo_url   : asText(raw.shop_logo_url),
        url             : asText(raw.url),
        shop_region     : asText(raw.shop_region),
        seller_location : asText(raw.seller_location),
        address         : asText(raw.address),
        phone           : asText(raw.phone),
        contact_name    : asText(raw.contact_name),
        sold_count      : asLong(raw.sold_count),
        review_count    : asLong(raw.review_count),
        followers_count : asLong(raw.followers_count),
        product_count   : asLong(raw.product_count),
        video_count     : asLong(raw.video_count),
        rating_score    : asDouble(raw.rating_score),
        is_official     : asBoolean(raw.is_official),
        domain          : asText(raw.domain) ?: 'shop.tiktok.com'
    ]
}

def unwrapActualResult(value) {
    if (!(value instanceof String)) return value

    def text = value.trim()

    if (!text || text == 'null') return []

    try {
        return new JsonSlurper().parseText(text)
    } catch (Exception ignored) {
        return []
    }
}

def collectShops(node, shops) {
    if (node instanceof Collection) {
        node.each { collectShops(it, shops) }
        return
    }

    if (!(node instanceof Map)) return

    // Envelope: { modelName, actualResult }
    if (node.containsKey('modelName')) {
        if (node.modelName?.toString() == 'TikTokShop') {
            collectShops(
                unwrapActualResult(node.actualResult),
                shops
            )
        }
        return
    }

    // Hỗ trợ shop object trực tiếp.
    def shop = toShop(node)

    if (shop != null) {
        shops << shop
    }
