import groovy.json.JsonSlurper
import groovy.json.JsonOutput
import groovy.transform.CompileStatic
import java.nio.charset.StandardCharsets
import org.apache.nifi.processor.io.InputStreamCallback
import org.apache.nifi.processor.io.OutputStreamCallback

@CompileStatic
class Utils {
    static String readUtf8NoBom(InputStream in) {
        byte[] b = in.bytes
        if (b.length >= 3 && (b[0] & 0xFF) == 0xEF && (b[1] & 0xFF) == 0xBB && (b[2] & 0xFF) == 0xBF) {
            return new String(b, 3, b.length - 3, StandardCharsets.UTF_8)
        }
        String s = new String(b, StandardCharsets.UTF_8)
        return (s && s.charAt(0) == '\uFEFF' as char) ? s.substring(1) : s
    }
    static boolean notEmpty(Object v) {
        if (v == null) return false
        if (v instanceof Collection) return !((Collection) v).isEmpty()
        return true
    }
    static Object clean(Object in) {
        if (in instanceof Map) {
            Map m = (Map) in
            Map out = new LinkedHashMap(m.size())
            for (def e : m.entrySet()) {
                Object cv = clean(e.value)
                if (cv != null && notEmpty(cv)) out.put(String.valueOf(e.key), cv)
            }
            return out
        } else if (in instanceof Collection) {
            List lst = new ArrayList(((Collection) in).size())
            for (Object it : (Collection) in) {
                Object cv = clean(it)
                if (cv != null && notEmpty(cv)) lst.add(cv)
            }
            return lst
        } else {
            return in
        }
    }

    /**
     * Validate JSON theo model GroupMemberBadge (đầu vào có badges: string[]):
     * - platform: string
     * - uid: string (bắt buộc)
     * - name: string
     * - group_id: string (bắt buộc)
     * - badges: string[] (đầu vào). Output: badge: string, id = platform_uid_group_id_<badgeNoSpaces>
     */
    static boolean isValidGroupMemberBadge(Map m) {
        if (m == null) return false
        def uid = m.get('uid')?.toString()?.trim()
        def groupId = m.get('group_id')?.toString()?.trim()
        if (!uid || !groupId) return false
        return true
    }

    static boolean isValidGroupMemberBadgeItem(Object item) {
        if (item instanceof Map) return isValidGroupMemberBadge((Map) item)
        return false
    }

    /** id = platform_uid_group_id hoặc platform_uid_group_id_<badgeNoSpaces> khi có badge */
    static String makeId(Map m, String badge = null) {
        def platform = m.get('platform')?.toString()?.trim() ?: 'facebook.com'
        def uid = m.get('uid')?.toString()?.trim() ?: ''
        def groupId = m.get('group_id')?.toString()?.trim() ?: ''
        def base = "${platform}_${uid}_${groupId}"
        if (badge != null && !badge.trim().isEmpty()) {
            return "${base}_${badge.replaceAll(/\s+/, '')}"
        }
        return base
    }

    /**
     * Chuyển 1 item (có badges[]) thành danh sách item mới: mỗi item có badge (string) và id = ..._badgeNoSpaces.
     * Nếu không có badge nào thì trả về 1 item với badge = null, id = platform_uid_group_id.
     */
    static List<Map> expandBadgesToItems(Map m) {
        def badges = m.get('badges')

        List<String> badgeList = new ArrayList<>()
        if (badges instanceof Collection) {
            for (Object it : (Collection) badges) {
                if (it == null) continue
                String s = it.toString().trim()
                if (s) badgeList.add(s)
            }
        } else if (badges != null) {
            String s = badges.toString().trim()
            if (s) badgeList.add(s)
        }

        Map base = new LinkedHashMap(m)
        base.remove('badges')

        long createdTime = (long) (System.currentTimeMillis() / 1000L)

        List<Map> result = new ArrayList<>()
        if (badgeList.isEmpty()) {
            base.put('badge', null)
            base.put('id', makeId(base, null))
            base.put('indexed_time', createdTime)
            result.add(base)
            return result
        }

        for (String badge : badgeList) {
            Map item = new LinkedHashMap(base)
            item.put('badge', badge)
            item.put('id', makeId(item, badge))
            item.put('indexed_time', createdTime)
            result.add(item)
        }

        return result
    }
}

