        if (Utils.isValidGroupMemberBadge(m)) {
            if (!m.containsKey('platform') || !m.get('platform')?.toString()?.trim()) {
                m.put('platform', 'facebook.com')
            }
            expanded.addAll(Utils.expandBadgesToItems(m))
