def sanitizeJson(value) {
    if (value == null) {
        return null
    }

    if (value instanceof Map) {
        return value.findAll { k, v ->
            v != null &&
            !(v instanceof Collection && v.isEmpty()) &&
            !(v instanceof Map && v.isEmpty()) &&
            !(v instanceof String && v.trim().isEmpty())
        }.collectEntries { k, v ->
            [(k): sanitizeJson(v)]
        }
    }

    if (value instanceof Collection) {
        return value.collect { sanitizeJson(it) }
            .findAll { it != null &&
                !(it instanceof Collection && it.isEmpty()) &&
                !(it instanceof Map && it.isEmpty()) &&
                !(it instanceof String && it.trim().isEmpty()) }
    }

    return value
}

def asNumber(value) {
    if (value == null || value instanceof Number) {
        return value
    }
    def text = value.toString().trim()
    if (!text) {
        return null
    }
    return text.contains('.') ? text.toDouble() : text.toLong()
}

def asStringList(value) {
    if (!(value instanceof Collection)) {
        return null
    }
    def items = value.findAll { it != null && it.toString().trim() }.collect { it.toString().trim() }
    return items ? items : null
}

def asBoolean(value) {
    if (value == null || value instanceof Boolean) {
        return value
    }
    def text = value.toString().trim().toLowerCase()
    if (text == 'true') {
        return true
    }
    if (text == 'false') {
        return false
    }
    return null
}

def asReviewer(value) {
    if (!(value instanceof Map)) {
        return null
    }

    def reviewer = [
        user_id           : value.user_id?.toString()?.trim(),
        name              : value.name?.toString()?.trim(),
        profile_url       : value.profile_url?.toString()?.trim(),
        profile_image     : value.profile_image?.toString()?.trim(),
        review_count      : asNumber(value.review_count),
        photo_count       : asNumber(value.photo_count),
        badge             : value.badge?.toString()?.trim(),
        is_local_guide    : asBoolean(value.is_local_guide),
        local_guide_level : asNumber(value.local_guide_level)
    ]
    return reviewer.values().any { it != null && !(it instanceof String && !it.trim()) } ? reviewer : null
}

def toReview(raw) {
    if (!(raw instanceof Map)) {
        return null
    }

    def reviewId = raw.review_id?.toString()?.trim()
    if (!reviewId) {
        return null
    }

    return [
        review_id      : reviewId,
        location_id    : raw.location_id?.toString()?.trim(),
        cid            : raw.cid?.toString()?.trim(),
        location_url   : raw.location_url?.toString()?.trim(),
        place_name     : raw.place_name?.toString()?.trim(),
