        review_url     : raw.review_url?.toString()?.trim(),
        user_id        : raw.user_id?.toString()?.trim(),
        user_name      : raw.user_name?.toString()?.trim(),
        rating         : asNumber(raw.rating),
        review_star    : asNumber(raw.review_star),
