        created_time   : raw.created_time?.toString()?.trim(),
        updated_time   : raw.updated_time?.toString()?.trim(),
        relative_time  : raw.relative_time?.toString()?.trim(),
        image_urls     : asStringList(raw.image_urls),
        photo          : asStringList(raw.photo),
        reviewer       : asReviewer(raw.reviewer)
    ]
}

def unwrapActualResult(value) {
    if (value instanceof String) {
        def text = value.trim()
        if (!text || text == 'null') {
            return []
        }
        return new JsonSlurper().parseText(text)
    }
    return value
}

def collectReviews(node, reviews) {
    if (node instanceof Collection && !(node instanceof Map)) {
        node.each { collectReviews(it, reviews) }
        return
    }
    if (!(node instanceof Map)) {
        return
    }

    if (node.modelName?.toString() == 'GoogleMapsReview') {
        collectReviews(unwrapActualResult(node.actualResult), reviews)
        return
    }

    def review = toReview(node)
    if (review) {
        reviews << review
        return
    }
}

