@GrabConfig(systemClassLoader=true)
import groovy.json.JsonSlurper
import groovy.json.JsonOutput
import groovy.transform.CompileStatic
import java.nio.charset.StandardCharsets
import org.apache.nifi.processor.io.InputStreamCallback
import org.apache.nifi.processor.io.OutputStreamCallback

@CompileStatic
class Utils {
    static String readUtf8NoBom(InputStream in) {
        byte[] b = in.bytes
        if (b.length >= 3 && (b[0] & 0xFF) == 0xEF && (b[1] & 0xFF) == 0xBB && (b[2] & 0xFF) == 0xBF) {
            return new String(b, 3, b.length - 3, StandardCharsets.UTF_8)
        }
        String s = new String(b, StandardCharsets.UTF_8)
        return (s.length() > 0 && s.charAt(0) == '\uFEFF' as char) ? s.substring(1) : s
    }
    static boolean notEmpty(Object v) {
        if (v == null) return false
        if (v instanceof Collection) return !((Collection) v).isEmpty()
        return true
    }
    // Loại bỏ null & collection rỗng (đệ quy, compile-time optimize)
    static Object clean(Object in) {
        if (in instanceof Map) {
            Map m = (Map) in
            Map out = new LinkedHashMap(m.size())
            for (def e : m.entrySet()) {
                Object cv = clean(e.value)
                if (cv != null && notEmpty(cv)) out.put(String.valueOf(e.key), cv)
            }
            return out
        } else if (in instanceof Collection) {
            List lst = new ArrayList(((Collection) in).size())
            for (Object it : (Collection) in) {
                Object cv = clean(it)
                if (cv != null && notEmpty(cv)) lst.add(cv)
            }
            return lst
        } else {
            return in
        }
    }
}

def flowFile = session.get()
if (!flowFile) return

try {
    // Đọc một lần + bỏ BOM
    String content = ''
    session.read(flowFile, { InputStream in -> content = Utils.readUtf8NoBom(in) } as InputStreamCallback)

    if (content == null || content.trim().isEmpty() || content.trim().equalsIgnoreCase('null')) {
        session.remove(flowFile)
        return
    }

    // Parse JSON
    def json
    try {
        json = new JsonSlurper().parseText(content)
    } catch (Exception e) {
        session.transfer(flowFile, REL_FAILURE)
        return
    }

    // B1: lọc null/rỗng
    json = Utils.clean(json)

    // B2: điều kiện: (entity_id || entity_username) & IntroInfos
    boolean ok = false
    if (json instanceof Map) {
        Map m = (Map) json
        boolean hasEntityIdOrUsername =
            (m.containsKey('entity_id') && m.get('entity_id')) ||
            (m.containsKey('entity_username') && m.get('entity_username'))
        boolean hasIntroInfos = m.containsKey('IntroInfos') && m.get('IntroInfos') != null

        if (hasEntityIdOrUsername && hasIntroInfos) {
            if (m.containsKey('entity_id') && m.get('entity_id') != null) {
                m.put('entity_id', String.valueOf(m.get('entity_id')))
            }
            ok = true
        }
    }

    // Ghi & chuyển
    byte[] outBytes = JsonOutput.toJson(json).getBytes(StandardCharsets.UTF_8) // không pretty để tiết kiệm CPU/I/O
    flowFile = session.write(flowFile, { OutputStream os -> os.write(outBytes) } as OutputStreamCallback)
    session.transfer(flowFile, ok ? REL_SUCCESS : REL_FAILURE)

} catch (Exception e) {
    log.error("ExecuteScript error", e)
    session.transfer(flowFile, REL_FAILURE)
}

import org.apache.nifi.flowfile.FlowFile
import groovy.json.JsonSlurper
import groovy.json.JsonOutput
import java.time.ZonedDateTime
import java.time.ZoneId
import java.time.format.DateTimeFormatter

def flowFile = session.get()
if (!flowFile) return

// ---------- 1. LẤY modelName & platform từ ATTRIBUTE ----------
def modelName = flowFile.getAttribute("modelName")
def platform  = flowFile.getAttribute("platform")

if (!modelName || !platform) {
    session.remove(flowFile)
    return
}

// ---------- 2. LẤY admin_id từ AMQP headers ----------
def headers = flowFile.getAttribute("amqp\$headers")
if (!headers) {
    session.remove(flowFile)
    return
}

def adminId = null
def s = headers.trim()
if (s.startsWith("{") && s.endsWith("}")) {
    s = s.substring(1, s.length() - 1)
}

s.split(",").each { pair ->
    int idx = pair.indexOf("=")
    if (idx > 0) {
        def key = pair.substring(0, idx).trim()
        if (key == "admin_id") {
            adminId = pair.substring(idx + 1).trim()
        }
    }
}

if (!adminId) {
    session.remove(flowFile)
    return
}

// ---------- 3. PARSE LIST JSON CONTENT ----------
def list
try {
    session.read(flowFile) { input ->
        list = new JsonSlurper().parse(input)
    }
} catch (Exception e) {
    session.remove(flowFile)
    return
}

if (!(list instanceof List)) {
    session.remove(flowFile)
    return
}

// ---------- 4. FOR từng item trong list ----------
def outputs = []

list.each { json ->
    if (!(json instanceof Map)) return

    def objectId = null

    switch (modelName) {
        case "AdsEntity":
            if (json.post_unique_id) {
                objectId = "${platform}_${json.post_unique_id}_${modelName}"
            }
            break

        case "CommentGraph":
            if (json.comment_id) {
                objectId = "${platform}_${json.comment_id}_${modelName}"
            }
            break

        case "GraphQLEntity":
            objectId = "${platform}_${json.uid}_${modelName}"
            break

        case "EntityAssociatedGroup":
            if (json.related_entity_id && json.entity_id && json.group_id && json.member_type) {
                objectId = "${platform}_${json.related_entity_id}_${json.entity_id}_${json.group_id}_${json.member_type}_${modelName}"
            }
            break

		case "EntityInfo":
			objectId = "${platform}_${UUID.randomUUID().toString()}_${modelName}"
			break

		case "GroupInfo":
            if (json.id) {
                objectId = "${platform}_${json.id}_${modelName}"
            }
            break

		case "ImageEntity":
            if (json.image_id) {
                objectId = "${platform}_${json.image_id}_${modelName}"
            }
            break

		case "PostContentGraph":
            if (json.post_id) {
                objectId = "${platform}_${json.post_id}_${modelName}"
            }
            break

		case "PostMarket":
            if (json.post_id) {
                objectId = "${platform}_${json.post_id}_${modelName}"
            }
            break

		case "ProfileSubCount":
            if (json.uid) {
                objectId = "${platform}_${json.uid}_${modelName}"
            }
            break

		case "UserFollowEntity":
            objectId =
				[[json.uid, json.uid_follower],
				 [json.username, json.uid_follower],
				 [json.uid, json.username_follower],
				 [json.username, json.username_follower]]
				.collect { a, b -> (a && b) ? "${platform}_${a}_${b}_${modelName}" : null }
				.find { it }
            break

		case "UserReaction":
            if (json.uid && json.object_id && json.reaction_id && json.reaction_type) {
                objectId = "${platform}_${json.uid}_${json.object_id}_${json.reaction_id}_${json.reaction_type}_${modelName}"
            }
            break

		case "VideoEntity":
            if (json.video_id) {
                objectId = "${platform}_${json.video_id}_${modelName}"
            }
            break

		case "LinkedInPost":
            if (json.post_id) {
                objectId = "${platform}_${json.post_id}_${modelName}"
            }
            break

		case "GraphQLCollection":
            if (json.collection_id) {
                objectId = "${platform}_${json.collection_id}_${modelName}"
            }
            break

		case "CommentDetail":
            if (json.CommentId) {
                objectId = "${platform}_${json.CommentId}_${modelName}"
            }
            break

		case "UserDetail":
            if (json.uid) {
                objectId = "${platform}_${json.uid}_${modelName}"
            }
            break

		case "GraphQLGroupMemberActivity":
            if (json.actor_id && json.group_id && json.object_id) {
                objectId = "${platform}_${json.actor_id}_${json.group_id}_${json.object_id}_${modelName}"
            }
            break

		case "MediaTracking":
            if (json.post_id && json.video_id && json.photo_id) {
                objectId = "${platform}_${json.post_id}_${json.video_id}_${json.photo_id}_${modelName}"
            }
            break
    }

    if (!objectId) return

    def createdTime = ZonedDateTime
            .now(ZoneId.of("Asia/Ho_Chi_Minh"))
            .format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss.SSS"))

    outputs << [
            object_id   : objectId,
            admin_id    : adminId,
            model       : modelName,
            platform    : platform,
            created_time: createdTime
    ]
}

// Không có record hợp lệ → drop
if (outputs.isEmpty()) {
    session.remove(flowFile)
    return
}

// ---------- 5. WRITE JSONEachRow ----------
def jsonArray = JsonOutput.toJson(outputs)

flowFile = session.write(flowFile) { out ->
    out.write(jsonArray.getBytes("UTF-8"))
}
flowFile = session.putAttribute(flowFile, "mime.type", "application/json")
flowFile = session.putAttribute(flowFile, "admin_id", adminId)
flowFile = session.putAttribute(flowFile, "kafka.key", "${platform}_${adminId}")

session.transfer(flowFile, REL_SUCCESS)
